def cross2(a,b):return a[...,0]*b[...,1]-a[...,1]*b[...,0]
def weights2(q,A):
 e=A[:,1]-A[:,0];f=A[:,2]-A[:,0];p=q-A[:,0];det=cross2(e,f);u=cross2(p,f)/det;v=cross2(e,p)/det;return np.column_stack((1-u-v,u,v))
